_PREPROCESSING_MANIFEST_SCHEMA = 1
_PREPROCESSING_REVISION = 1


@dataclass(frozen=True)
class PreprocessingResult:
    """Published preprocessing-cache identity and location."""

    cache_version: str
    manifest_path: Path
    output_dir: Path
    processed: int
    reused: bool


def _canonical_json(value):
    return json.dumps(
        value, sort_keys=True, separators=(',', ':'), ensure_ascii=True, allow_nan=False
    )


def _json_sha256(value):
    return hashlib.sha256(_canonical_json(value).encode('utf-8')).hexdigest()


def _source_file_signature(path):
    """Return a cheap signature without reading file contents."""
    resolved = Path(path).expanduser().resolve(strict=True)
    stat = resolved.stat()
    return {
        'path': str(resolved),
        'size': int(stat.st_size),
        'mtime_ns': int(stat.st_mtime_ns),
    }


def _transform_cache_specs(transforms):
    """Serialize transforms sufficiently to make cache reuse fail closed."""
    specs = []
    for transform in transforms or []:
        if isinstance(transform, dict) or hasattr(transform, 'to_spec'):
            specs.append(transforms_to_specs([transform])[0])
            continue
        live = getattr(transform, 'tio_transform', transform)
        if isinstance(live, tio.Transform):
            representation = repr(live)
            if ' at 0x' in representation:
                raise TypeError(
                    f'{type(transform).__name__} has no stable cache representation. '
                    'Use an allow-listed fastMONAI transform with to_spec().'
                )
            specs.append({
                'kind': 'torchio',
                'class': f'{type(live).__module__}.{type(live).__qualname__}',
                'repr': representation,
            })
            continue
        raise TypeError(
            f'{type(transform).__name__} cannot be represented in a preprocessing cache '
            'contract. Use a fastMONAI transform with to_spec().'
        )
    return specs


def _live_preprocessing_transforms(transforms):
    live = []
    for transform in transforms or []:
        if isinstance(transform, dict):
            transform = build_transform_from_spec(transform)
        live.append(getattr(transform, 'tio_transform', transform))
    return live


def _preprocessing_contract(target_spacing, apply_reorder, transforms, has_mask):
    spacing = None if target_spacing is None else [float(value) for value in target_spacing]
    return {
        'preprocessing_revision': _PREPROCESSING_REVISION,
        'apply_reorder': bool(apply_reorder),
        'target_spacing': spacing,
        'has_mask': bool(has_mask),
        'transforms': _transform_cache_specs(transforms),
    }


def _safe_cache_relative_path(value):
    relative = Path(value)
    if relative.is_absolute() or '..' in relative.parts:
        raise ValueError(f'Unsafe preprocessing output path in manifest: {value!r}')
    return relative


def _read_valid_preprocessing_manifest(cache_dir, expected_version, contract, sources):
    manifest_path = cache_dir / 'preprocessing_manifest.json'
    try:
        manifest = json.loads(manifest_path.read_text(encoding='utf-8'))
        if (
            manifest.get('manifest_schema') != _PREPROCESSING_MANIFEST_SCHEMA
            or manifest.get('preprocessing_cache_version') != expected_version
            or manifest.get('contract') != contract
            or manifest.get('sources') != sources
        ):
            return None
        outputs = manifest.get('outputs')
        if not isinstance(outputs, list) or len(outputs) != len(sources):
            return None

        expected_paths = {
            str(Path('images') / Path(source['image']['path']).name)
            for source in sources
        }
        expected_paths.update(
            str(Path('masks') / Path(source['mask']['path']).name)
            for source in sources if source['mask'] is not None
        )
        manifest_paths = []
        for output in outputs:
            for role in ('image', 'mask'):
                entry = output.get(role)
                if entry is None:
                    continue
                relative = _safe_cache_relative_path(entry['path'])
                size = entry.get('size')
                if not isinstance(size, int) or size <= 0:
                    return None
                path = cache_dir / relative
                if not path.is_file() or path.stat().st_size != size:
                    return None
                manifest_paths.append(str(relative))
        if len(manifest_paths) != len(expected_paths) or set(manifest_paths) != expected_paths:
            return None
    except (OSError, KeyError, TypeError, ValueError, json.JSONDecodeError):
        return None
    return manifest


def _publish_preprocessing_cache(stage_dir, cache_dir):
    """Publish a complete staged cache, restoring an existing cache on failure."""
    backup_dir = None
    if cache_dir.exists():
        backup_dir = cache_dir.parent / f'.{cache_dir.name}.old-{uuid.uuid4().hex}'
        os.rename(cache_dir, backup_dir)
    try:
        os.rename(stage_dir, cache_dir)
    except Exception:
        if backup_dir is not None and backup_dir.exists() and not cache_dir.exists():
            os.rename(backup_dir, cache_dir)
        raise
    if backup_dir is not None:
        shutil.rmtree(backup_dir)


def preprocess_dataset(df, img_col, mask_col=None, output_dir='preprocessed',
                       target_spacing=None, apply_reorder=True, transforms=None,
                       max_workers=4, skip_existing=True, dataset_version=None):
    """Preprocess a dataset into a manifest-validated, fingerprinted disk cache.

    Cache identity covers the optional mask-based dataset_version, preprocessing
    contract, and cheap source signatures (resolved path, size, and nanosecond mtime).
    A complete cache is published only after every case succeeds and the manifest is
    written. The DataFrame receives output paths only after publication.

    Transform pipeline order:
        CopyAffine (if masks) -> ToCanonical (if apply_reorder)
        -> Resample (if target_spacing) -> user transforms

    Args:
        df: DataFrame with file paths.
        img_col: Column name for image paths.
        mask_col: Optional column name for mask paths.
        output_dir: Cache root. A versioned child directory is created below it.
        target_spacing: Target voxel spacing for resampling.
        apply_reorder: Whether to reorder to RAS+ canonical orientation.
        transforms: Additional TorchIO or serializable fastMONAI transforms.
        max_workers: Number of parallel volume workers.
        skip_existing: Reuse a valid matching cache. False explicitly rebuilds it.
        dataset_version: Optional existing dataset/annotation fingerprint to bind to
            this cache. Raw image contents are not read to compute the cache version.

    Returns:
        PreprocessingResult describing the published or reused cache.
    """
    if len(df) == 0:
        raise ValueError('DataFrame is empty')
    if img_col not in df.columns:
        raise ValueError(f"Column '{img_col}' not found in DataFrame")
    if mask_col is not None and mask_col not in df.columns:
        raise ValueError(f"Column '{mask_col}' not found in DataFrame")
    if dataset_version is not None and not isinstance(dataset_version, str):
        raise TypeError('dataset_version must be a string or None')

    img_names = [Path(path).name for path in df[img_col]]
    if len(set(img_names)) != len(img_names):
        duplicates = {name for name in img_names if img_names.count(name) > 1}
        raise ValueError(f'Duplicate image file names: {duplicates}')

    if mask_col is not None:
        mask_names = [Path(path).name for path in df[mask_col]]
        if len(set(mask_names)) != len(mask_names):
            duplicates = {name for name in mask_names if mask_names.count(name) > 1}
            raise ValueError(f'Duplicate mask file names: {duplicates}')

    contract = _preprocessing_contract(
        target_spacing, apply_reorder, transforms, mask_col is not None
    )
    case_sources = []
    for position in range(len(df)):
        image_signature = _source_file_signature(df[img_col].iloc[position])
        mask_signature = (
            _source_file_signature(df[mask_col].iloc[position])
            if mask_col is not None else None
        )
        case_sources.append({'image': image_signature, 'mask': mask_signature})
    sources = sorted(case_sources, key=_canonical_json)

    version_payload = {
        'manifest_schema': _PREPROCESSING_MANIFEST_SCHEMA,
        'dataset_version': dataset_version,
        'contract': contract,
        'sources': sources,
    }
    cache_version = _json_sha256(version_payload)
    cache_root = Path(output_dir).expanduser()
    cache_dir = cache_root / cache_version
    img_dir = cache_dir / 'images'
    mask_dir = cache_dir / 'masks' if mask_col is not None else None

    existing = _read_valid_preprocessing_manifest(
        cache_dir, cache_version, contract, sources
    ) if cache_dir.is_dir() else None
    if existing is not None and skip_existing:
        df[f'{img_col}_preprocessed'] = [
            str(img_dir / Path(path).name) for path in df[img_col]
        ]
        if mask_col is not None:
            df[f'{mask_col}_preprocessed'] = [
                str(mask_dir / Path(path).name) for path in df[mask_col]
            ]
        print(f'Preprocessing complete: 0 processed, {len(df)} skipped, 0 failed')
        return PreprocessingResult(
            cache_version, cache_dir / 'preprocessing_manifest.json',
            cache_dir, processed=0, reused=True,
        )
    if cache_dir.exists() and existing is None and skip_existing:
        raise RuntimeError(
            f'Preprocessing cache exists but has no valid matching manifest: {cache_dir}. '
            'Pass skip_existing=False to rebuild it explicitly.'
        )

    cache_root.mkdir(parents=True, exist_ok=True)
    stage_dir = cache_root / f'.{cache_version}.tmp-{uuid.uuid4().hex}'
    stage_img_dir = stage_dir / 'images'
    stage_mask_dir = stage_dir / 'masks' if mask_col is not None else None
    stage_img_dir.mkdir(parents=True)
    if stage_mask_dir is not None:
        stage_mask_dir.mkdir()

    all_transforms = []
    if mask_col is not None:
        all_transforms.append(tio.CopyAffine(target='image'))
    if apply_reorder:
        all_transforms.append(tio.ToCanonical())
    if target_spacing is not None:
        all_transforms.append(tio.Resample(target_spacing))
    all_transforms.extend(_live_preprocessing_transforms(transforms))
    pipeline = tio.Compose(all_transforms) if all_transforms else None

    work_items = []
    for position in range(len(df)):
        image_path = df[img_col].iloc[position]
        mask_path = df[mask_col].iloc[position] if mask_col is not None else None
        work_items.append({
            'image_path': image_path,
            'mask_path': mask_path,
            'out_image': stage_img_dir / Path(image_path).name,
            'out_mask': (
                stage_mask_dir / Path(mask_path).name if mask_col is not None else None
            ),
        })

    def _process_case(item):
        subject_dict = {'image': tio.ScalarImage(item['image_path'])}
        if item['mask_path'] is not None:
            subject_dict['mask'] = tio.LabelMap(item['mask_path'])
        subject = tio.Subject(**subject_dict)
        if pipeline is not None:
            subject = pipeline(subject)

        out_image = item['out_image']
        tmp_image = out_image.parent / f'.tmp_{out_image.name}'
        subject['image'].save(str(tmp_image))
        os.rename(tmp_image, out_image)

        if item['out_mask'] is not None:
            out_mask = item['out_mask']
            tmp_mask = out_mask.parent / f'.tmp_{out_mask.name}'
            subject['mask'].save(str(tmp_mask))
            os.rename(tmp_mask, out_mask)

    failures = []
    try:
        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            futures = {
                executor.submit(_process_case, item): item for item in work_items
            }
            for future in tqdm(
                as_completed(futures), total=len(futures), desc='Preprocessing'
            ):
                item = futures[future]
                try:
                    future.result()
                except Exception as error:
                    failures.append((str(item['image_path']), str(error)))

        if failures:
            examples = failures[:5]
            raise RuntimeError(
                f'{len(failures)} case(s) failed preprocessing; no cache was published. '
                f'First failures: {examples}'
            )

        outputs = []
        for item in work_items:
            image_path = item['out_image']
            image_entry = {
                'path': str(image_path.relative_to(stage_dir)),
                'size': int(image_path.stat().st_size),
            }
            mask_entry = None
            if item['out_mask'] is not None:
                mask_path = item['out_mask']
                mask_entry = {
                    'path': str(mask_path.relative_to(stage_dir)),
                    'size': int(mask_path.stat().st_size),
                }
            outputs.append({'image': image_entry, 'mask': mask_entry})
        outputs.sort(key=_canonical_json)

        manifest = {
            **version_payload,
            'preprocessing_cache_version': cache_version,
            'outputs': outputs,
        }
        manifest_path = stage_dir / 'preprocessing_manifest.json'
        manifest_path.write_text(
            json.dumps(manifest, indent=2, sort_keys=True) + '\n', encoding='utf-8'
        )
        _publish_preprocessing_cache(stage_dir, cache_dir)
    except Exception:
        if stage_dir.exists():
            shutil.rmtree(stage_dir)
        raise

    df[f'{img_col}_preprocessed'] = [
        str(img_dir / Path(path).name) for path in df[img_col]
    ]
    if mask_col is not None:
        df[f'{mask_col}_preprocessed'] = [
            str(mask_dir / Path(path).name) for path in df[mask_col]
        ]

    print(f'Preprocessing complete: {len(work_items)} processed, 0 skipped, 0 failed')
    return PreprocessingResult(
        cache_version, cache_dir / 'preprocessing_manifest.json',
        cache_dir, processed=len(work_items), reused=False,
    )


